import re

def parse_log_file(input_file, output_file):
    with open(input_file, 'r') as f:
        log_data = f.read()

    # regex per trovare tutti i tipi di format
    formats = re.findall(r'format:\s*(\w+)', log_data)

    # rimuove i duplicati e ordina in ordine alfabetico
    unique_formats = sorted(set(formats))

    # scrive i risultati nel file di output
    with open(output_file, 'w') as f:
        for fmt in unique_formats:
            f.write(fmt + '\n')
            